"""Build worker/test/fixtures/seed_etl.sql: the ETL's own test fixtures (real SEC rows) run through etl.transform.

Run from etl/:  uv run python ../worker/test/fixtures/make_seed.py
The output is committed so `npm test` needs no Python. synthetic.sql (hand-written, fake names) is loaded after it.
"""

from __future__ import annotations

import sqlite3
import tempfile
import zipfile
from pathlib import Path

from etl import transform as T

ROOT = Path(__file__).resolve().parents[3]
FIX = ROOT / "etl" / "tests" / "fixtures"
OUT = Path(__file__).with_name("seed_etl.sql")
TABLES = ("advisers", "funds", "fund_file_nos", "formd_offerings", "meta")


def lit(v) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, (int, float)):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


def main() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        zips = Path(tmp) / "formd"
        zips.mkdir()
        for q in sorted((FIX / "formd").iterdir()):
            with zipfile.ZipFile(zips / f"{q.name}.zip", "w") as zf:
                for f in q.iterdir():
                    zf.write(f, f"{q.name.upper()}/{f.name}")
        out = Path(tmp) / "fund.db"
        T.build(FIX / "adv", zips, out, "2008-01-01")
        db = sqlite3.connect(out)
        lines = ["-- Generated by make_seed.py from etl/tests/fixtures (real SEC rows). Do not edit."]
        for t in TABLES:
            where = " WHERE key NOT IN ('built_at')" if t == "meta" else ""
            cur = db.execute(f"SELECT * FROM {t}{where} ORDER BY 1")
            cols = ", ".join(d[0] for d in cur.description)
            for row in cur:
                lines.append(f"INSERT INTO {t} ({cols}) VALUES ({', '.join(lit(v) for v in row)});")
    OUT.write_text("\n".join(lines) + "\n")
    print(f"wrote {OUT} ({len(lines) - 1} rows)")


if __name__ == "__main__":
    main()
